 1→{
 2→  "name": "onchainchess-mcp",
 3→  "version": "1.0.0",
 4→  "description": "MCP server for AI agents to play chess on onchainchess.com",
 5→  "type": "module",
 6→  "main": "index.js",
 7→  "scripts": {
 8→    "start": "node index.js"
 9→  },
10→  "dependencies": {
11→    "@modelcontextprotocol/sdk": "^1.12.1",
12→    "ws": "^8.18.0",
13→    "zod": "^3.24.4"
14→  }
15→}
16→

  1→import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
  2→import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
  3→import { z } from 'zod';
  4→import { ChessApiClient, ApiError } from './api-client.js';
  5→import { loadCredentials, saveCredentials } from './auth-store.js';
  6→
  7→const serverUrl = process.env.CHESS_SERVER_URL || 'http://localhost:3001';
  8→const client = new ChessApiClient(serverUrl);
  9→
 10→const server = new McpServer({
 11→  name: 'onchainchess',
 12→  version: '1.0.0',
 13→});
 14→
 15→function requireAuth() {
 16→  const creds = loadCredentials();
 17→  if (!creds) {
 18→    throw new Error('No account found. Use create_account first.');
 19→  }
 20→  return creds;
 21→}
 22→
 23→function errorResponse(err) {
 24→  const message = err instanceof ApiError
 25→    ? err.message
 26→    : err.message || 'Unknown error';
 27→  const result = { error: message };
 28→  if (err instanceof ApiError && err.body?.legalMoves) {
 29→    result.legalMoves = err.body.legalMoves;
 30→  }
 31→  return { content: [{ type: 'text', text: JSON.stringify(result) }], isError: true };
 32→}
 33→
 34→function ok(data) {
 35→  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
 36→}
 37→
 38→// 1. create_account
 39→server.tool(
 40→  'create_account',
 41→  'Create a bot account on onchainchess.com. Only needed once — credentials are saved to disk.',
 42→  { username: z.string().min(3).max(32).describe('Username (3-32 chars, alphanumeric + hyphens)') },
 43→  async ({ username }) => {
 44→    try {
 45→      const existing = loadCredentials();
 46→      if (existing) {
 47→        return errorResponse(new Error(`Account already exists: ${existing.username}. Delete ~/.onchainchess-bot to create a new one.`));
 48→      }
 49→      const result = await client.signup(username);
 50→      saveCredentials(result.username, result.token);
 51→      return ok({ username: result.username, message: 'Account created and saved.' });
 52→    } catch (err) {
 53→      return errorResponse(err);
 54→    }
 55→  }
 56→);
 57→
 58→// 2. create_game
 59→server.tool(
 60→  'create_game',
 61→  'Create a new chess game room. Returns an invite code to share with your opponent.',
 62→  { color: z.enum(['white', 'black', 'random']).default('random').describe('Which color to play as') },
 63→  async ({ color }) => {
 64→    try {
 65→      const { token } = requireAuth();
 66→      const room = await client.createRoom(token, color);
 67→      return ok({ roomId: room.roomId, inviteCode: room.inviteCode, color: room.color });
 68→    } catch (err) {
 69→      return errorResponse(err);
 70→    }
 71→  }
 72→);
 73→
 74→// 3. wait_for_opponent
 75→server.tool(
 76→  'wait_for_opponent',
 77→  'Wait for an opponent to join your game room. Blocks until someone joins or timeout.',
 78→  {
 79→    room_id: z.number().describe('Room ID to wait in'),
 80→    timeout_seconds: z.number().default(300).describe('Max seconds to wait (default 300)'),
 81→  },
 82→  async ({ room_id, timeout_seconds }) => {
 83→    try {
 84→      const { token } = requireAuth();
 85→
 86→      // Pre-check: maybe opponent already joined
 87→      const state = await client.getRoomState(token, room_id);
 88→      if (state.status === 'playing') {
 89→        return ok({
 90→          status: 'playing',
 91→          opponent_username: state.white?.username === state.myUsername ? state.black?.username : state.white?.username,
 92→        });
 93→      }
 94→
 95→      // Wait via WebSocket
 96→      const msg = await client.waitForEvent(token, room_id, ['join'], timeout_seconds * 1000);
 97→      return ok({
 98→        status: 'playing',
 99→        opponent_username: msg.data?.username,
100→        opponent_color: msg.data?.color,
101→      });
102→    } catch (err) {
103→      return errorResponse(err);
104→    }
105→  }
106→);
107→
108→// 4. join_game
109→server.tool(
110→  'join_game',
111→  'Join an existing game using an invite code.',
112→  { invite_code: z.string().describe('The invite code shared by the game creator') },
113→  async ({ invite_code }) => {
114→    try {
115→      const { token } = requireAuth();
116→      const result = await client.joinRoom(token, invite_code);
117→      return ok({ roomId: result.roomId, color: result.color });
118→    } catch (err) {
119→      return errorResponse(err);
120→    }
121→  }
122→);
123→
124→// 5. get_board_state
125→server.tool(
126→  'get_board_state',
127→  'Get the current board state, legal moves, and game status.',
128→  { room_id: z.number().describe('Room ID') },
129→  async ({ room_id }) => {
130→    try {
131→      const { token } = requireAuth();
132→      const state = await client.getRoomState(token, room_id);
133→      return ok(state);
134→    } catch (err) {
135→      return errorResponse(err);
136→    }
137→  }
138→);
139→
140→// 6. make_move
141→server.tool(
142→  'make_move',
143→  'Make a chess move in UCI format (e.g. "e2e4", "e7e8q" for promotion).',
144→  {
145→    room_id: z.number().describe('Room ID'),
146→    move: z.string().describe('Move in UCI format: source+target+promotion (e.g. "e2e4", "e7e8q")'),
147→  },
148→  async ({ room_id, move }) => {
149→    try {
150→      const { token } = requireAuth();
151→      const result = await client.submitMove(token, room_id, move);
152→      return ok(result);
153→    } catch (err) {
154→      return errorResponse(err);
155→    }
156→  }
157→);
158→
159→// 7. wait_for_turn
160→server.tool(
161→  'wait_for_turn',
162→  'Wait for it to be your turn (or game over). Blocks until opponent moves or timeout.',
163→  {
164→    room_id: z.number().describe('Room ID'),
165→    timeout_seconds: z.number().default(300).describe('Max seconds to wait (default 300)'),
166→  },
167→  async ({ room_id, timeout_seconds }) => {
168→    try {
169→      const { token } = requireAuth();
170→
171→      // Pre-check: maybe it's already our turn or game is over
172→      const state = await client.getRoomState(token, room_id);
173→      if (state.status === 'finished' || state.currentTurn === state.myColor) {
174→        return ok(state);
175→      }
176→
177→      // Wait via WebSocket for move or gameOver
178→      const msg = await client.waitForEvent(token, room_id, ['move', 'gameOver'], timeout_seconds * 1000);
179→
180→      if (msg.event === 'gameOver') {
181→        return ok({ gameOver: true, result: msg.data?.result, reason: msg.data?.reason });
182→      }
183→
184→      // After receiving a move event, fetch full state for consistency
185→      const updated = await client.getRoomState(token, room_id);
186→      return ok(updated);
187→    } catch (err) {
188→      return errorResponse(err);
189→    }
190→  }
191→);
192→
193→// 8. resign
194→server.tool(
195→  'resign',
196→  'Resign the current game.',
197→  { room_id: z.number().describe('Room ID') },
198→  async ({ room_id }) => {
199→    try {
200→      const { token } = requireAuth();
201→      const result = await client.resign(token, room_id);
202→      return ok(result);
203→    } catch (err) {
204→      return errorResponse(err);
205→    }
206→  }
207→);
208→
209→// Prompt: instructs the agent how to play a chess game
210→server.prompt(
211→  'play_chess',
212→  'Instructions for playing a chess game efficiently',
213→  () => ({
214→    messages: [{
215→      role: 'user',
216→      content: {
217→        type: 'text',
218→        text: `You are playing chess on onchainchess.com via MCP tools. Follow these rules strictly:
219→
220→1. SILENT PLAY: Do NOT output any text between moves. No commentary, no analysis, no narration. Just call tools silently.
221→2. GAME LOOP: After setup (create/join game), repeat: wait_for_turn → get_board_state → make_move. Do not pause or speak between these calls.
222→3. ONLY SPEAK when: the game ends (report result), an unrecoverable error occurs, or you need info from the user (like an invite code).
223→4. Move selection: Pick the best move from legalMoves. Don't explain your reasoning.
224→5. If a move is rejected, silently retry with a legal move.
225→
226→Start by asking the user how they want to set up the game, then go silent until it's over.`
227→      }
228→    }]
229→  })
230→);
231→
232→// Start
233→const transport = new StdioServerTransport();
234→await server.connect(transport);
235→

  1→import WebSocket from 'ws';
  2→
  3→export class ChessApiClient {
  4→  constructor(serverUrl) {
  5→    this.serverUrl = serverUrl.replace(/\/$/, '');
  6→    this.wsUrl = this.serverUrl.replace(/^http/, 'ws');
  7→  }
  8→
  9→  async signup(username) {
 10→    const res = await fetch(`${this.serverUrl}/api/auth/signup`, {
 11→      method: 'POST',
 12→      headers: { 'Content-Type': 'application/json' },
 13→      body: JSON.stringify({ username }),
 14→    });
 15→    const body = await res.json();
 16→    if (!res.ok) throw new ApiError(res.status, body.error || 'Signup failed');
 17→    return body;
 18→  }
 19→
 20→  async createRoom(token, color) {
 21→    const res = await fetch(`${this.serverUrl}/api/rooms`, {
 22→      method: 'POST',
 23→      headers: {
 24→        'Content-Type': 'application/json',
 25→        Authorization: `Bearer ${token}`,
 26→      },
 27→      body: JSON.stringify({ color }),
 28→    });
 29→    const body = await res.json();
 30→    if (!res.ok) throw new ApiError(res.status, body.error || 'Failed to create room');
 31→    return body;
 32→  }
 33→
 34→  async joinRoom(token, inviteCode) {
 35→    const res = await fetch(`${this.serverUrl}/api/rooms/join`, {
 36→      method: 'POST',
 37→      headers: {
 38→        'Content-Type': 'application/json',
 39→        Authorization: `Bearer ${token}`,
 40→      },
 41→      body: JSON.stringify({ inviteCode }),
 42→    });
 43→    const body = await res.json();
 44→    if (!res.ok) throw new ApiError(res.status, body.error || 'Failed to join room');
 45→    return body;
 46→  }
 47→
 48→  async getRoomState(token, roomId) {
 49→    const res = await fetch(`${this.serverUrl}/api/rooms/${roomId}`, {
 50→      headers: { Authorization: `Bearer ${token}` },
 51→    });
 52→    const body = await res.json();
 53→    if (!res.ok) throw new ApiError(res.status, body.error || 'Failed to get room state');
 54→    return body;
 55→  }
 56→
 57→  async submitMove(token, roomId, move) {
 58→    const res = await fetch(`${this.serverUrl}/api/rooms/${roomId}/move`, {
 59→      method: 'POST',
 60→      headers: {
 61→        'Content-Type': 'application/json',
 62→        Authorization: `Bearer ${token}`,
 63→      },
 64→      body: JSON.stringify({ move }),
 65→    });
 66→    const body = await res.json();
 67→    if (!res.ok) throw new ApiError(res.status, body.error || 'Move failed', body);
 68→    return body;
 69→  }
 70→
 71→  async resign(token, roomId) {
 72→    const res = await fetch(`${this.serverUrl}/api/rooms/${roomId}/resign`, {
 73→      method: 'POST',
 74→      headers: { Authorization: `Bearer ${token}` },
 75→    });
 76→    const body = await res.json();
 77→    if (!res.ok) throw new ApiError(res.status, body.error || 'Resign failed');
 78→    return body;
 79→  }
 80→
 81→  waitForEvent(token, roomId, targetEvents, timeoutMs = 300000) {
 82→    return new Promise((resolve, reject) => {
 83→      const wsUrl = `${this.wsUrl}/api/rooms/${roomId}/ws?token=${token}`;
 84→      const ws = new WebSocket(wsUrl);
 85→
 86→      const timer = setTimeout(() => {
 87→        ws.close();
 88→        reject(new Error(`Timed out waiting for events: ${targetEvents.join(', ')}`));
 89→      }, timeoutMs);
 90→
 91→      ws.on('message', (data) => {
 92→        try {
 93→          const msg = JSON.parse(data.toString());
 94→          if (targetEvents.includes(msg.event)) {
 95→            clearTimeout(timer);
 96→            ws.close();
 97→            resolve(msg);
 98→          }
 99→        } catch {
100→          // ignore malformed messages
101→        }
102→      });
103→
104→      ws.on('error', (err) => {
105→        clearTimeout(timer);
106→        ws.close();
107→        reject(new Error(`WebSocket error: ${err.message}`));
108→      });
109→
110→      ws.on('close', (code) => {
111→        clearTimeout(timer);
112→        // Only reject if we haven't resolved yet
113→        if (code !== 1000) {
114→          reject(new Error(`WebSocket closed unexpectedly (code ${code})`));
115→        }
116→      });
117→    });
118→  }
119→}
120→
121→export class ApiError extends Error {
122→  constructor(status, message, body) {
123→    super(message);
124→    this.status = status;
125→    this.body = body;
126→  }
127→}
