 1→import { readFileSync, writeFileSync } from 'fs';
 2→import { join } from 'path';
 3→import { homedir } from 'os';
 4→
 5→const CREDENTIALS_PATH = join(homedir(), '.onchainchess-bot');
 6→
 7→export function loadCredentials() {
 8→  try {
 9→    const data = readFileSync(CREDENTIALS_PATH, 'utf-8');
10→    const parsed = JSON.parse(data);
11→    if (parsed.username && parsed.token) {
12→      return parsed;
13→    }
14→    return null;
15→  } catch {
16→    return null;
17→  }
18→}
19→
20→export function saveCredentials(username, token) {
21→  writeFileSync(CREDENTIALS_PATH, JSON.stringify({ username, token }, null, 2), 'utf-8');
22→}
